//! - Entries: 1686

/// The longest key Appendix A enumerates, in code points.
///
/// Measured from the table below rather than assumed.
/// `xtask attest` asserts the value this engine is written against, so a revision adding a
/// three-code-point member is a build failure rather than a silent truncation.
///
/// JLReq: §A
pub(crate) const MAX_KEY_LEN: usize = 2;

/// The frame (字幅) mask bit for the full ideographic em (全角, full-width).
///
/// JLReq: §A Remarks
pub(crate) const FRAME_FULL_EM: u8 = 0b0000_0001;

/// The frame (字幅) mask bit for half an em (半角, `half-width` in the Remarks column).
///
/// JLReq: §A Remarks
pub(crate) const FRAME_HALF_EM: u8 = 0b0000_0010;

/// The frame (字幅) mask bit for a third of an em (三分角, `one third em width`).
///
/// JLReq: §A Remarks
pub(crate) const FRAME_THIRD_EM: u8 = 0b0000_0100;

/// The frame (字幅) mask bit for a quarter em (四分角, `quarter em width`).
///
/// JLReq: §A Remarks
pub(crate) const FRAME_QUARTER_EM: u8 = 0b0000_1000;

/// The frame (字幅) mask bit for a per-glyph advance (プロポーショナル, `proportionally-spaced`).
///
/// JLReq: §A Remarks
pub(crate) const FRAME_PROPORTIONAL: u8 = 0b0001_0000;

/// The empty frame mask: the Remarks cell states no frame at all.
///
/// JLReq: §A Remarks
pub(crate) const FRAMES_UNSTATED: u8 = 0b0000_0000;

/// The writing-direction qualification: the Remarks cell restricts the writing direction in no way.
///
/// JLReq: §A Remarks
pub(crate) const USAGE_UNQUALIFIED: u8 = 0;

/// The writing-direction qualification: `used in horizontal composition` (横組で使用).
///
/// JLReq: §A Remarks
pub(crate) const USAGE_HORIZONTAL_ONLY: u8 = 1;

/// The writing-direction qualification: `used in vertical composition` (縦組で使用).
///
/// JLReq: §A Remarks
pub(crate) const USAGE_VERTICAL_ONLY: u8 = 2;

/// The role a Remarks cell may name: the Remarks cell names no role.
///
/// JLReq: §A Remarks
pub(crate) const ROLE_UNSTATED: u8 = 0;

/// The role a Remarks cell may name: `decimal point` (小数点).
///
/// JLReq: §A Remarks
pub(crate) const ROLE_DECIMAL_POINT: u8 = 1;

/// The role a Remarks cell may name: the digit-grouping space or comma (位取りの空白, 位取りのコンマ).
///
/// JLReq: §A Remarks
pub(crate) const ROLE_DIGIT_GROUP_SEPARATOR: u8 = 2;

/// One distinct Remarks cell of Appendix A, and the facts it states.
///
/// JLReq: §A Remarks
#[derive(Debug)]
pub(crate) struct Remark {
    /// The English half of the cell, verbatim, with its line break kept.
    pub(crate) en: &'static str,
    /// The Japanese half, likewise. Three cells carry no English at all, which
    /// is a recorded defect of the published document rather than an omission
    /// here.
    pub(crate) ja: &'static str,
    /// The frames the cell permits, as a mask.
    pub(crate) frames: u8,
    /// The writing-direction qualification it carries.
    pub(crate) usage: u8,
    /// The role it names.
    pub(crate) role: u8,
}

