/// One Appendix A listing: one key, one class that names it, and the Remarks cell
/// that listing carries.
///
/// Keyed by a listing rather than by a key, because two in five keys are named by
/// more than one class and the Remarks cell that separates them belongs to the
/// row, not to the key (`docs/adr/0008`).
///
/// JLReq: §A
#[derive(Debug)]
pub(crate) struct Listing {
    /// The key, as code points, zero beyond `key_len`.
    pub(crate) key: [u32; MAX_KEY_LEN],
    /// How many code points of `key` are the key.
    pub(crate) key_len: u8,
    /// The class that lists the key, `1` through `30`.
    pub(crate) class: u8,
    /// Which `REMARKS` entry this listing's Remarks cell holds.
    pub(crate) remark: u8,
}

impl Listing {
    /// One row of the table below.
    const fn new(key: [u32; MAX_KEY_LEN], key_len: u8, class: u8, remark: u8) -> Self {
        Self {
            key,
            key_len,
            class,
            remark,
        }
    }
}

